),
dpit(seg,d) AS (VALUES
  ('PJ_RECURRENTE', -0.08021654934077671),
  ('PJ_NUEVO', -0.0850093167369432),
  ('PN_NUEVO', -0.08775014913008303),
  ('PN_RECURRENTE', -0.0955348945847789)
),
base AS (
  SELECT m.cod_mes, m.cod_tip_doc, m.key_value, m.pd_raw,
    (CASE WHEN m.cod_tip_doc='1' THEN 'PN' ELSE 'PJ' END || '_' || m.desc_cliente) AS seg,
    CASE WHEN m.pd_raw IS NOT NULL THEN 1 ELSE 0 END AS flg_cruce
  FROM disc_model_owner.b46029_desemb_cal_corr_202609 m
),
sc AS (
  SELECT b.*,
    greatest(1e-4, least(1-1e-4, ii.y0+(ii.y1-ii.y0)*CASE WHEN ii.x1=ii.x0 THEN 0 ELSE (b.pd_raw-ii.x0)/(ii.x1-ii.x0) END)) AS pd_iso,
    ftd.ftv AS ft_pbi, dp.d AS dpit
  FROM base b
  LEFT JOIN iso ii ON ii.seg=b.seg AND b.pd_raw>=ii.x0 AND b.pd_raw<ii.x1
  LEFT JOIN ftd ON ftd.cm=b.cod_mes
  LEFT JOIN dpit dp ON dp.seg=b.seg
),
c AS (
  SELECT sc.*, CASE WHEN flg_cruce=1 THEN normal_cdf(0.0,1.0, 0.9606554637821979*inverse_normal_cdf(0.0,1.0,pd_iso)+-0.04174354786746397*ft_pbi+dpit) END AS pd_pit
  FROM sc
),
nuevo AS (
  SELECT c.cod_mes, c.cod_tip_doc, c.key_value, c.flg_cruce,
    CASE WHEN c.flg_cruce=1 THEN (
      CASE WHEN round((1-greatest(1e-6,least(1-1e-6, c.pd_pit*(CASE WHEN c.seg='PJ_RECURRENTE' AND c.cod_mes>=202501 THEN 0.72 WHEN c.seg='PN_RECURRENTE' AND c.cod_mes>=202501 THEN 0.82 ELSE 1.0 END))))*1000) >= 969 THEN 'G1'
           WHEN round((1-greatest(1e-6,least(1-1e-6, c.pd_pit*(CASE WHEN c.seg='PJ_RECURRENTE' AND c.cod_mes>=202501 THEN 0.72 WHEN c.seg='PN_RECURRENTE' AND c.cod_mes>=202501 THEN 0.82 ELSE 1.0 END))))*1000) >= 947 THEN 'G2'
           WHEN round((1-greatest(1e-6,least(1-1e-6, c.pd_pit*(CASE WHEN c.seg='PJ_RECURRENTE' AND c.cod_mes>=202501 THEN 0.72 WHEN c.seg='PN_RECURRENTE' AND c.cod_mes>=202501 THEN 0.82 ELSE 1.0 END))))*1000) >= 911 THEN 'G3'
           WHEN round((1-greatest(1e-6,least(1-1e-6, c.pd_pit*(CASE WHEN c.seg='PJ_RECURRENTE' AND c.cod_mes>=202501 THEN 0.72 WHEN c.seg='PN_RECURRENTE' AND c.cod_mes>=202501 THEN 0.82 ELSE 1.0 END))))*1000) >= 904 THEN 'G4'
           WHEN round((1-greatest(1e-6,least(1-1e-6, c.pd_pit*(CASE WHEN c.seg='PJ_RECURRENTE' AND c.cod_mes>=202501 THEN 0.72 WHEN c.seg='PN_RECURRENTE' AND c.cod_mes>=202501 THEN 0.82 ELSE 1.0 END))))*1000) >= 887 THEN 'G5'
           ELSE 'G6' END) END AS grupo_new
  FROM c
)
SELECT o.grupo_cal AS g_viejo_rec, nuevo.grupo_new AS g_corr_v1, COUNT(*) AS n
FROM disc_model_owner.b46029_desemb_maestra_rec_202609 o
JOIN nuevo ON o.cod_mes=nuevo.cod_mes AND o.cod_tip_doc=nuevo.cod_tip_doc AND o.key_value=nuevo.key_value
WHERE o.flg_cruce=1 AND nuevo.flg_cruce=1
GROUP BY o.grupo_cal, nuevo.grupo_new
ORDER BY o.grupo_cal, nuevo.grupo_new
